import { useEffect, useState } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate, useNavigate } from 'react-router-dom';
import './App.css';
import AdminDashboard from './components/AdminDashboard/AdminDashboard';
import LoginPage from './components/LoginPage';
import RegisterPage from './components/RegisterPage';
import StudentDashboard from './components/StudentDashboard/StudentDashboard';
import api, { getToken, clearToken } from './api';

// Route Guard Component
const ProtectedRoute = ({ user, allowedRole, children }) => {
  if (!user) {
    return <Navigate to="/login" replace />;
  }
  if (allowedRole && user.role !== allowedRole) {
    // Redirect unauthorized non-admin users to student page
    return <Navigate to={user.role === 'admin' ? '/admin' : '/student'} replace />;
  }
  return children;
};

function AppContent() {
  const [loading, setLoading] = useState(true);
  const [currentUser, setCurrentUser] = useState(null);
  const [prefilledCredentials, setPrefilledCredentials] = useState({ email: '', password: '' });
  const navigate = useNavigate();

  useEffect(() => {
    const token = getToken();
    if (!token) {
      setLoading(false);
      return;
    }

    api
      .me()
      .then((user) => {
        setCurrentUser(user);
      })
      .catch(() => {
        clearToken();
      })
      .finally(() => {
        setLoading(false);
      });
  }, []);

  const handleRegisterSuccess = ({ email, password }) => {
    setPrefilledCredentials({ email, password });
    navigate('/login');
  };

  const handleLoginSuccess = (user) => {
    setCurrentUser(user);
    if (user.role === 'admin') {
      navigate('/admin');
    } else {
      navigate('/student');
    }
  };

  const handleLogout = () => {
    clearToken();
    setCurrentUser(null);
    navigate('/login');
  };

  if (loading) {
    return <div className="app-container">Loading...</div>;
  }

  return (
    <div className="app-container">
      <Routes>
        {/* Default Redirect */}
        <Route
          path="/"
          element={
            currentUser ? (
              <Navigate to={currentUser.role === 'admin' ? '/admin' : '/student'} replace />
            ) : (
              <Navigate to="/login" replace />
            )
          }
        />

        {/* Public Auth Routes */}
        <Route
          path="/login"
          element={
            <LoginPage
              initialEmail={prefilledCredentials.email}
              initialPassword={prefilledCredentials.password}
              onLoginSuccess={handleLoginSuccess}
              onNavigateToRegister={() => navigate('/register')}
            />
          }
        />
        <Route
          path="/register"
          element={
            <RegisterPage
              onRegisterSuccess={handleRegisterSuccess}
              onNavigateToLogin={() => navigate('/login')}
            />
          }
        />

        {/* Protected Student Route */}
        <Route
          path="/student"
          element={
            <ProtectedRoute user={currentUser} allowedRole="student">
              <StudentDashboard currentUser={currentUser} onLogout={handleLogout} />
            </ProtectedRoute>
          }
        />

        {/* Protected Admin Route */}
        <Route
          path="/admin/*"
          element={
            <ProtectedRoute user={currentUser} allowedRole="admin">
              <AdminDashboard currentUser={currentUser} onLogout={handleLogout} />
            </ProtectedRoute>
          }
        />

        {/* Fallback Wildcard Route */}
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </div>
  );
}

export default function App() {
  return (
    <Router>
      <AppContent />
    </Router>
  );
}
